	if string(retrievedValue) != string(value) {
		fmt.Printf("ERROR: Expected '%s', got '%s'\n", string(value), string(retrievedValue))
		os.Exit(1)
	}

	fmt.Println("SUCCESS: Get method works correctly after removing unnecessary Commit()")
}
EOF
